WITH incoming AS ( SELECT * FROM unnest($2::uuid[], $3::text[], $4::email_recipient_type[]) AS t(contact_id, name, recipient_type) ), removed AS ( DELETE FROM email_message_recipients WHERE message_id = $1::uuid AND (contact_id, recipient_type) NOT IN ( SELECT contact_id, recipient_type FROM incoming ) ) INSERT INTO email_message_recipients (message_id, contact_id, name, recipient_type) SELECT $1, contact_id, name, recipient_type FROM incoming ON CONFLICT (message_id, contact_id, recipient_type) DO NOTHING
